@Test
void attachedLeaseExitClosesOnlyConnectionAndLeavesHostSessionUsable() throws Exception {
    var provider = new ScriptedModelProvider();
    var store = new MemoryHostStore();
    var permissions = new PermissionBroker(Clock.systemUTC());
    var connectionClosed = new AtomicBoolean();
    try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
            .permissionDecider(permissions).build();
         var sessions = new SessionApplicationService(runtime)) {
        var prompts = new PromptApplicationService(sessions, store);
        String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
        int exit = JiCli.acp(new String[]{"acp", "--protocol", "v1", "--stdio"}, Map.of(),
                new ByteArrayInputStream(new byte[0]), new PrintStream(new ByteArrayOutputStream()),
                ignored -> AcpRuntimeLease.attached(sessions, prompts, permissions,
                        new ModelRef("faux", "faux-1"), () -> connectionClosed.set(true)));
        assertEquals(0, exit);
        assertTrue(connectionClosed.get());
        assertEquals(sessionId, sessions.load(sessionId).id());
    }
}

@Test
void privateLeaseExitCancelsRunPersistsTerminalStateAndClosesRuntime() throws Exception {
    var gate = new ScriptedModelProvider.Gate();
    var provider = new ScriptedModelProvider().enqueue(List.of(
            new ScriptedModelProvider.Step.Wait(gate),
            new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
    var store = new MemoryHostStore();
    var permissions = new PermissionBroker(Clock.systemUTC());
    var runtimeClosed = new AtomicBoolean();
    var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
            .permissionDecider(permissions).build();
    var sessions = new SessionApplicationService(runtime);
    var prompts = new PromptApplicationService(sessions, store);
    String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
    prompts.prompt(sessionId, "command-private", "wait");
    long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
    while (!sessions.hasActiveRun(sessionId) && System.nanoTime() < deadline) Thread.onSpinWait();
    assertTrue(sessions.hasActiveRun(sessionId));
    int exit = JiCli.acp(new String[]{"acp", "--protocol", "v1", "--stdio"}, Map.of(),
            new ByteArrayInputStream(new byte[0]), new PrintStream(new ByteArrayOutputStream()),
            ignored -> AcpRuntimeLease.privateRuntime(sessions, prompts, permissions,
                    new ModelRef("faux", "faux-1"), () -> {
                        runtime.close();
                        runtimeClosed.set(true);
                    }));
    assertEquals(0, exit);
    assertTrue(runtimeClosed.get());
    assertTrue(store.load(sessionId).orElseThrow().execution().activeRun().isEmpty());
    assertEquals("ABORTED", store.load(sessionId).orElseThrow().execution().completedRuns().getLast()
            .outcome().orElseThrow().name());
}

